// DEV_RIO_701 アフィリエイト【下書き準備のみ・dry-run】。
// 記事に対する『アフィリンク挿入案』を生成する。★実リンク生成・自動埋め込み・公開はしない。
// 偽のアフィリエイトURLは作らない。人間が自分のアフィリID付きリンクをプレースホルダに差し込む。
const i = $input.first().json;
return [{ json: {
  content_id: i.content_id ?? 'ca-aff-001',
  title: i.title ?? '（タイトル未設定）',
  source_excerpt: (i.note_body ?? i.note_draft_body ?? '').slice(0, 600),
  platform: 'note',
  action_type: 'prepare_affiliate_suggestions'
} }];

parameters.jsonBody:
{
  "model": "claude-haiku-4-5-20251001",
  "max_tokens": 1024,
  "messages": [
    {
      "role": "user",
      "content": "以下の記事に自然に差し込めるアフィリエイト商品の提案を最大3件。各: 商品ジャンル(book/tool/service等)、記事内の挿入位置の説明、20字以内のアンカー文。実在を断定しない。JSON配列のみ: [{\"genre\":\"...\",\"placement\":\"...\",\"anchor\":\"...\"}]。\n\nタイトル: {{ $json.title }}\n本文抜粋: {{ $json.source_excerpt }}"
    }
  ]
}

parameters.jsCode:
// Claude応答をパース。各提案に『リンク差し込み欄(プレースホルダ)』を付与して停止。
const prev = $input.first().json;
let suggestions = [];
try {
  const text = prev?.content?.[0]?.text ?? '[]';
  const match = text.match(/\[[\s\S]*\]/);
  suggestions = match ? JSON.parse(match[0]) : [];
} catch (e) {
  suggestions = [{ genre: 'parse_error', placement: '', anchor: '手動で作成', error: String(e) }];
}
const ctx = $('Ingest Content').first().json;
const enriched = suggestions.map((s, idx) => ({
  ...s,
  affiliate_link_placeholder: `<<ここに自分の楽天/AmazonアフィリID付きリンクを貼る #${idx + 1}>>`
}));
return [{ json: {
  content_id: ctx.content_id,
  suggestions: enriched,
  suggestion_count: enriched.length,
  state: 'WAITING_APPROVAL',
  published: false,
  note: 'dry-run。アフィリ挿入案のみ。★実リンク生成・自動埋め込み・公開はしない。人間が自分のアフィリID付きリンクをプレースホルダに差し込み、手動で反映する。'
} }];
